catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {

        g_form.setMandatory('counterparty_description', false);
        g_form.setMandatory('entity', false);
        g_form.setMandatory('business_process', false);
        g_form.setMandatory('email_type', false);
        g_form.setMandatory('email_address', false);
        g_form.setMandatory('email_automation', false);
		g_form.setMandatory('contact_type', false);

        g_form.setReadOnly('active', true);
        g_form.setReadOnly('counterparty_description', true);
        g_form.setReadOnly('entity', true);
        g_form.setReadOnly('business_process', true);
        g_form.setReadOnly('email_type', true);
        g_form.setReadOnly('email_address', true);
        g_form.setReadOnly('contact_type', true);
        g_form.setReadOnly('contact_number', true);
        g_form.setReadOnly('email_automation', true);
        g_form.setReadOnly('external_or_internal', true);
        g_form.setReadOnly('high_priority_client', true);
        g_form.setReadOnly('comments', true);

    } else {

        g_form.setMandatory('counterparty_description', true);
        g_form.setMandatory('entity', true);
        g_form.setMandatory('business_process', true);
        g_form.setMandatory('email_type', true);
        g_form.setMandatory('email_address', true);
        g_form.setMandatory('email_automation', true);
		g_form.setMandatory('contact_type', true);

        g_form.setReadOnly('active', false);
        g_form.setReadOnly('counterparty_description', false);
        g_form.setReadOnly('entity', false);
        g_form.setReadOnly('business_process', false);
        g_form.setReadOnly('email_type', false);
        g_form.setReadOnly('email_address', false);
        g_form.setReadOnly('contact_type', false);
        g_form.setReadOnly('contact_number', false);
        g_form.setReadOnly('email_automation', false);
        g_form.setReadOnly('external_or_internal', false);
        g_form.setReadOnly('high_priority_client', false);
        g_form.setReadOnly('comments', false);
    }
}
